// D, the documentation bundle of EA1 (engine-aware design §5.2): null-graph's agent guide, its API pages, its
// migration notes, the package README and the runnable starters, copied with their source, size and hash, and read
// only by id and line range. Generated by dev/engine-bundle.mjs; the review lists the stale mentions a reviewer
// accepted, each with its reason (compat.json; scan.ts finds them). Frozen at load: a read returns what was hashed.

import docsText from './docs.json?raw';
import { deepFreeze } from './frozen';
import type { StaleMention } from './scan';

export { staleMentions, type StaleMention } from './scan';

export interface EngineDoc {
    /** `agent/guide`, `api/<page>`, `npm/readme` or `example/<scene>`. */
    id: string;
    title: string;
    /** Where it was copied from: `null-graph@<commit>:<path>` or `npm:null-graph@<version>/<path>`. */
    source: string;
    bytes: number;
    lines: number;
    sha256: string;
    /** LF line ends. */
    text: string;
}

export const DOCS = deepFreeze(JSON.parse(docsText) as {
    version: string;
    /** `null-graph@<commit>`, or `null-graph@<commit>+worktree` for a release not yet committed there. */
    source: string;
    /** The bundled files that differ from that commit (worktree bundles only). */
    uncommitted: string[];
    docs: EngineDoc[];
    review: { stale: (StaleMention & { reason: string })[] };
});

/** The most lines one read returns (the design's `read_doc`). */
export const READ_LIMIT = 160;

const BY_ID = new Map(DOCS.docs.map(d => [d.id, d]));

/** One read: the lines, where they start and end (1-based, inclusive), the document's length, and whether its end cut the read short. */
export interface DocRead {
    id: string;
    sha256: string;
    start: number;
    end: number;
    total: number;
    truncated: boolean;
    lines: readonly string[];
}

/**
 * Lines `start` to `start + count - 1` (1-based) of one document, with its hash. A read that runs past the document's
 * end stops at its last line and says so (`truncated`, `end`); an unknown document or a start outside it is refused.
 */
export function readDoc(id: string, start: number, count: number): DocRead {
    const doc = BY_ID.get(id);
    if (!doc) throw new Error(`no document ${id} in the bundle`);
    if (!Number.isInteger(count) || count < 1 || count > READ_LIMIT) throw new Error(`a read is 1 to at most ${READ_LIMIT} lines, not ${count}`);
    if (!Number.isInteger(start) || start < 1 || start > doc.lines) throw new Error(`${id} has lines 1 to ${doc.lines}; ${start} is outside them`);
    const end = Math.min(doc.lines, start + count - 1);
    return { id, sha256: doc.sha256, start, end, total: doc.lines, truncated: end < start + count - 1, lines: doc.text.split('\n').slice(start - 1, end) };
}
